const fa=new Intl.NumberFormat('fa-IR');const usd=new Intl.NumberFormat('en-US');
const presets={start:{name:'شروع',sizes:[5000,10000,20000],prices:{5000:11,10000:14,20000:26},split:60,loss:3,phases:2,cap:10},standard:{name:'استاندارد',sizes:[10000,50000,100000],prices:{10000:25,50000:149,100000:309},split:80,loss:6,phases:2,cap:0},single:{name:'تک‌مرحله‌ای',sizes:[10000,50000,100000],prices:{10000:79,50000:339,100000:549},split:80,loss:3,phases:1,cap:0}};
let currentPreset='standard',currentSize=100000;
function renderBuilder(){const p=presets[currentPreset];if(!p.sizes.includes(currentSize))currentSize=p.sizes[p.sizes.length-1];document.querySelectorAll('[data-preset]').forEach(b=>{const active=b.dataset.preset===currentPreset;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelector('#builder-sizes').innerHTML=p.sizes.map(size=>`<button data-builder-size="${size}" class="${size===currentSize?'active':''}" aria-pressed="${size===currentSize}">${usd.format(size/1000)}k</button>`).join('');document.querySelector('#target').textContent=p.phases===2?'۵٪ + ۱۰٪':'۱۰٪';document.querySelector('#max-loss').textContent=fa.format(p.loss)+'٪';document.querySelector('#cap').textContent=p.cap?fa.format(currentSize*p.cap/100)+' دلار':'بدون سقف';document.querySelector('#account-value').textContent='$'+usd.format(currentSize);document.querySelector('#profit-split').textContent=fa.format(p.split)+'٪';document.querySelector('#split-ring').style.background=`conic-gradient(#75e4aa ${p.split}%,#284a31 ${p.split}%)`;document.querySelector('#split-ring span').textContent=p.split+'/'+(100-p.split);document.querySelector('#card-preset').textContent='چالش '+p.name+' · '+(p.phases===2?'۲ مرحله‌ای':'۱ مرحله‌ای');document.querySelector('#phase-two').hidden=p.phases===1;document.querySelector('#phase-two').nextElementSibling.hidden=p.phases===1;document.querySelector('#builder-price').textContent='$'+usd.format(p.prices[currentSize]);}
renderBuilder();document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{currentPreset=b.dataset.preset;renderBuilder()}));document.querySelector('#builder-sizes').addEventListener('click',e=>{const b=e.target.closest('[data-builder-size]');if(!b)return;currentSize=Number(b.dataset.builderSize);renderBuilder()});
function selectSize(size){currentSize=size;currentPreset=size<=20000?'start':'standard';renderBuilder();document.querySelectorAll('[data-size]').forEach(b=>{const active=Number(b.dataset.size)===size;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}document.querySelectorAll('[data-size]').forEach(b=>b.addEventListener('click',()=>selectSize(Number(b.dataset.size))));
const dialog=document.querySelector('#selection-dialog');function openReview(){const p=presets[currentPreset];document.querySelector('#selection-summary').innerHTML=[['پلن','چالش '+p.name],['اندازهٔ حساب','$'+usd.format(currentSize)],['هزینهٔ نمونه','$'+usd.format(p.prices[currentSize])],['سهم سود',fa.format(p.split)+'٪'],['افت کل / زیان روزانه',fa.format(p.loss)+'٪ / ۳٪'],['سقف برداشت',p.cap?'$'+usd.format(currentSize*p.cap/100):'بدون سقف']].map(([label,value])=>`<div><span>${label}</span><b ${value.startsWith('$')?'dir="ltr"':''}>${value}</b></div>`).join('');dialog.showModal()}document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>{currentPreset=b.dataset.plan;currentSize=currentPreset==='start'?5000:100000;renderBuilder();openReview()}));document.querySelector('#review-selection').addEventListener('click',openReview);document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());document.querySelector('#dialog-done').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
const menu=document.querySelector('.menu');const links=document.querySelector('.navlinks');function closeMenu(){links.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','باز کردن منو')}menu.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'بستن منو':'باز کردن منو')});links.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
